"use client";

import { useEffect, useState } from "react";
import { createClient } from "@/lib/supabase/client";

type Currency = {
  id: string;
    code: string;
      name: string;
      };

      export default function ObservationForm() {
        const [currencies, setCurrencies] = useState<Currency[]>([]);
          const [currencyId, setCurrencyId] = useState("");
            const [rate, setRate] = useState("");
              const [observedAt, setObservedAt] = useState("");
                const [marketSide, setMarketSide] = useState("reference");
                  const [loading, setLoading] = useState(false);
                    const [loadingCurrencies, setLoadingCurrencies] = useState(true);
                      const [message, setMessage] = useState("");
                        const [error, setError] = useState("");

                          const supabase = createClient();

                            useEffect(() => {
                                async function loadCurrencies() {
                                      const { data, error } = await supabase
                                              .from("currencies")
                                                      .select("id, code, name")
                                                              .in("code", ["USD", "EUR", "MLC"])
                                                                      .eq("is_active", true)
                                                                              .order("code");

                                                                                    if (error) {
                                                                                            setError("No se pudieron cargar las monedas.");
                                                                                                  } else {
                                                                                                          setCurrencies(data || []);
                                                                                                                }

                                                                                                                      setLoadingCurrencies(false);
                                                                                                                          }

                                                                                                                              loadCurrencies();
                                                                                                                                }, []);

                                                                                                                                  async function handleSubmit(
                                                                                                                                      event: React.FormEvent<HTMLFormElement>
                                                                                                                                        ) {
                                                                                                                                            event.preventDefault();

                                                                                                                                                setMessage("");
                                                                                                                                                    setError("");

                                                                                                                                                        if (!currencyId || !rate || !observedAt) {
                                                                                                                                                              setError("Completa todos los campos.");
                                                                                                                                                                    return;
                                                                                                                                                                        }

                                                                                                                                                                            const numericRate = Number(rate);

                                                                                                                                                                                if (!Number.isFinite(numericRate) || numericRate <= 0) {
                                                                                                                                                                                      setError("Introduce una tasa válida mayor que cero.");
                                                                                                                                                                                            return;
                                                                                                                                                                                                }

                                                                                                                                                                                                    setLoading(true);

                                                                                                                                                                                                        const { data, error } = await supabase.rpc(
                                                                                                                                                                                                              "create_observation",
                                                                                                                                                                                                                    {
                                                                                                                                                                                                                            p_currency_id: currencyId,
                                                                                                                                                                                                                                    p_rate_cup: numericRate,
                                                                                                                                                                                                                                            p_observed_at: new Date(observedAt).toISOString(),
                                                                                                                                                                                                                                                    p_market_side: marketSide,
                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                  if (error) {
                                                                                                                                                                                                                                                                        setError("No se pudo registrar la observación. Comprueba tus permisos e inténtalo nuevamente.");
                                                                                                                                                                                                                                                                            } else {
                                                                                                                                                                                                                                                                                  setMessage(
                                                                                                                                                                                                                                                                                          `Observación registrada correctamente. ID: ${data}. Estado: pendiente de revisión.`
                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                      setRate("");
                                                                                                                                                                                                                                                                                                            setObservedAt("");
                                                                                                                                                                                                                                                                                                                  setMarketSide("reference");
                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                          setLoading(false);
                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                              return (
                                                                                                                                                                                                                                                                                                                                  <section className="mt-8 rounded-2xl border border-yellow-500/20 bg-[#11151c] p-6">
                                                                                                                                                                                                                                                                                                                                        <h2 className="text-xl font-bold text-white">
                                                                                                                                                                                                                                                                                                                                                Registrar nueva tasa
                                                                                                                                                                                                                                                                                                                                                      </h2>

                                                                                                                                                                                                                                                                                                                                                            <p className="mt-2 text-sm text-gray-400">
                                                                                                                                                                                                                                                                                                                                                                    Las observaciones registradas quedarán pendientes de revisión.
                                                                                                                                                                                                                                                                                                                                                                          </p>

                                                                                                                                                                                                                                                                                                                                                                                <form onSubmit={handleSubmit} className="mt-6 space-y-5">
                                                                                                                                                                                                                                                                                                                                                                                        <div>
                                                                                                                                                                                                                                                                                                                                                                                                  <label className="mb-2 block text-sm text-gray-300">
                                                                                                                                                                                                                                                                                                                                                                                                              Moneda
                                                                                                                                                                                                                                                                                                                                                                                                                        </label>

                                                                                                                                                                                                                                                                                                                                                                                                                                  <select
                                                                                                                                                                                                                                                                                                                                                                                                                                              value={currencyId}
                                                                                                                                                                                                                                                                                                                                                                                                                                                          onChange={(e) => setCurrencyId(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      required
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  disabled={loadingCurrencies}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              className="w-full rounded-xl border border-white/10 bg-[#080b10] p-3 text-white"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <option value="">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {loadingCurrencies ? "Cargando monedas..." : "Seleccionar moneda"}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </option>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {currencies.map((currency) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <option key={currency.id} value={currency.id}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {currency.code} — {currency.name}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </select>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <label className="mb-2 block text-sm text-gray-300">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Tasa en CUP
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </label>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  type="number"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              min="0.000001"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          step="any"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      required
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  value={rate}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              onChange={(e) => setRate(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          placeholder="Ejemplo: 500"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      className="w-full rounded-xl border border-white/10 bg-[#080b10] p-3 text-white"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <label className="mb-2 block text-sm text-gray-300">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Fecha y hora de observación
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </label>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      type="datetime-local"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  required
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              value={observedAt}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onChange={(e) => setObservedAt(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      className="w-full rounded-xl border border-white/10 bg-[#080b10] p-3 text-white"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <label className="mb-2 block text-sm text-gray-300">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Tipo de operación
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </label>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <select
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      value={marketSide}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onChange={(e) => setMarketSide(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              className="w-full rounded-xl border border-white/10 bg-[#080b10] p-3 text-white"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <option value="reference">Referencia</option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <option value="buy">Compra</option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <option value="sell">Venta</option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </select>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {error && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p className="rounded-xl border border-red-500/30 bg-red-500/10 p-3 text-sm text-red-300">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {error}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {message && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p className="break-words rounded-xl border border-green-500/30 bg-green-500/10 p-3 text-sm text-green-300">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {message}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                type="submit"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          disabled={loading || loadingCurrencies || currencies.length === 0}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    className="w-full rounded-xl bg-yellow-500 px-4 py-3 font-bold text-black hover:bg-yellow-400 disabled:opacity-50"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {loading ? "Registrando..." : "Registrar observación"}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </section>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }